const qrSvg = seed => { let s = seed, cells=''; const r = () => (s = (s*9301+49297)%233280)/233280; const N=21;
  const fin = (x,y) => `<rect x="${x}" y="${y}" width="7" height="7" fill="#1a181b"/><rect x="${x+1}" y="${y+1}" width="5" height="5" fill="#fff"/><rect x="${x+2}" y="${y+2}" width="3" height="3" fill="#1a181b"/>`;
  for (let y=0;y<N;y++) for (let x=0;x<N;x++){ const inF = (x<8&&y<8)||(x>12&&y<8)||(x<8&&y>12); if(!inF && r()>.52) cells+=`<rect x="${x}" y="${y}" width="1" height="1" fill="#1a181b"/>`; }
  return `<svg viewBox="-1 -1 23 23" role="img" aria-label="Invite QR code"><rect x="-1" y="-1" width="23" height="23" fill="#fff"/>${cells}${fin(0,0)}${fin(14,0)}${fin(0,14)}</svg>`; };

